import json
from pathlib import Path
import statistics
import time

import chess
import torch

from harbichess.backends.torch_network import load_weights, sha256
from harbichess.chess.actions import legal_action_indices
from harbichess.chess.encoding import BoardEncoder

torch.set_num_threads(1);torch.use_deterministic_algorithms(True)
root=Path('/workspace/HarbiChess');directory=root/'artifacts/ufuk-broad-v4-strength-arena-20261004'
r=json.loads((root/'artifacts/ufuk-broad-v4-training-controller-20261004/learning-gates.json').read_text());assert r['status']=='pass-learning-only' and r['both_seeds_passed'];r['source_commit']='70c612572e03f562f21469e546823244083a3b4a';
assert json.loads((directory/'result.json').read_text())['status']=='completed-awaiting-independent-game-audit-and-strength-gates'
probes=root/'docs/research/UFUK-width-latency-probes-20261004.json'
setup=time.perf_counter();paths={'original':root/'artifacts/ufuk-all-train-20261003/checkpoints/step-009250/model.safetensors',**{arm:Path(info['directory'])/'model.safetensors' for arm,info in r['seeds']['20261026']['selected'].items()}}
assert sha256(probes)=='1089fd0cca308c24bb040a840352d0ad18aa85a7bdcd17608133456bf08bed9f'
models={arm:load_weights(path).eval() for arm,path in paths.items()};inputs=[]
for row in json.loads(probes.read_text())['positions']:
    board=chess.Board(row['root_fen'])
    for uci in row['moves']:board.push_uci(uci)
    assert board.fen()==row['fen'];inputs.append((torch.tensor(BoardEncoder().encode_board(board).values).reshape(1,8,8,104),torch.tensor([legal_action_indices(board)])))
with torch.no_grad():
    for _ in range(10):
        for x,actions in inputs:
            for model in models.values():
                p,v=model.masked_policy_value(x,actions);assert torch.isfinite(p).all() and torch.isfinite(v).all()
    setup_wall=time.perf_counter()-setup;started=time.perf_counter();samples={arm:[] for arm in models}
    for repeat in range(200):
        order=['original','control','candidate'];order=order[repeat%3:]+order[:repeat%3]
        for x,actions in inputs:
            for arm in order:
                start=time.perf_counter_ns();p,v=models[arm].masked_policy_value(x,actions);elapsed=time.perf_counter_ns()-start
                samples[arm].append(elapsed);assert torch.isfinite(p).all() and torch.isfinite(v).all()
summaries={arm:{'calls':len(s),'median_ns':statistics.median(s),'p95_ns':sorted(s)[int(.95*len(s))],'mean_ns':statistics.mean(s),'nanoseconds':s} for arm,s in samples.items()}
ratios={arm:summary['median_ns']/summaries['original']['median_ns'] for arm,summary in summaries.items() if arm!='original'}
report={'schema':1,'source_commit':r['source_commit'],'ratios_vs_original':ratios,'gates':{arm:ratio<=1.10 for arm,ratio in ratios.items()},'limit':1.10,'weights_sha256':{arm:sha256(path) for arm,path in paths.items()},'probe_sha256':sha256(probes),'cpu_threads':1,'batch':1,'mode':'eager legal masked full policy+value','warmup_rounds':10,'timed_rounds':200,'setup_and_warmup_wall_seconds_excluded':setup_wall,'measurement_outer_wall_seconds':time.perf_counter()-started,'samples':summaries,'scope':'Warmed inference only; full tasks matched, rotation among3models. No concurrent training; encoding/search/startup/game throughput excluded; failed learning stays failed.'}
report['candidate_vs_control_ratio']=summaries['candidate']['median_ns']/summaries['control']['median_ns'];report['speed_gate_passed']=ratios['candidate']<=1.10 and report['candidate_vs_control_ratio']<=1.10;report['gates']={'candidate_vs_initial':ratios['candidate']<=1.10,'candidate_vs_control':report['candidate_vs_control_ratio']<=1.10};report['script_sha256']=sha256(Path(__file__));report['scope']='Registered18full-history/10warmup/200rounds same-architecture legal-maskedB1policy+WDLFP32CPU1 latency, rotating3armorder. Encoding/setup excluded, whole parent300second budget recorded separately. No concurrent training/benchmark; no whole-game speed/self-learning/Stockfish-level claim.'
p=directory/'latency.json';assert not p.exists();p.write_text(json.dumps(report,indent=2)+'\n');print(json.dumps({k:v for k,v in report.items() if k!='samples'}),flush=True)
